package com.fasterxml.jackson.databind.deser.impl;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.BeanDescription;
import com.fasterxml.jackson.databind.MapperConfig;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.deser.CreatorProperty;
import com.fasterxml.jackson.databind.deser.SettableBeanProperty;
import com.fasterxml.jackson.databind.deser.ValueInstantiator;
import com.fasterxml.jackson.databind.deser.std.StdValueInstantiator;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Member;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class CreatorCollector_verifyNonDup_TriageGen0Test {

    private CreatorCollector creatorCollector;
    private BeanDescription beanDesc;
    private MapperConfig<?> config;

    // Subclass to expose the protected method for testing
    private static class TestableCreatorCollector extends CreatorCollector {
        public TestableCreatorCollector(BeanDescription beanDesc, MapperConfig<?> config) {
            super(beanDesc, config);
        }

        @Override
        public void verifyNonDup(AnnotatedWithParams newOne, int typeIndex, boolean explicit) {
            super.verifyNonDup(newOne, typeIndex, explicit);
        }

        // Mocking _fixAccess as it is likely a protected method that might involve complex logic
        @Override
        protected AnnotatedWithParams _fixAccess(AnnotatedWithParams param) {
            return param;
        }
    }

    @Before
    public void setUp() {
        beanDesc = mock(BeanDescription.class);
        config = mock(MapperConfig.class);
        creatorCollector = new TestableCreatorCollector(beanDesc, config);
    }

    @Test
    public void testVerifyNonDup_FirstTime_NoExplicit() {
        AnnotatedWithParams newOne = mock(AnnotatedWithParams.class);
        creatorCollector.verifyNonDup(newOne, 0, false);

        assertTrue(creatorCollector.hasDefaultCreator());
        // Check if it was actually stored (using reflection or internal state if possible, 
        // but here we rely on behavior or the fact that it doesn't throw)
    }

    @Test
    public void testVerifyNonDup_FirstTime_WithExplicit() {
        AnnotatedWithParams newOne = mock(AnnotatedWithParams.class);
        creatorCollector.verifyNonDup(newOne, 0, true);

        assertTrue(creatorCollector.hasDefaultCreator());
    }

    @Test
    public void testVerifyNonDup_AlreadyHasExplicit_NewIsImplicit_ShouldReturn() {
        AnnotatedWithParams oldOne = mock(AnnotatedWithParams.class);
        AnnotatedWithParams newOne = mock(AnnotatedWithParams.class);

        // Setup state: first call with explicit
        creatorCollector.verifyNonDup(oldOne, 0, true);

        // Second call with implicit
        creatorCollector.verifyNonDup(newOne, 0, false);

        // If it returned early, the creator at index 0 remains oldOne
        // We can't easily check _creators directly without reflection, 
        // but this test ensures no exception is thrown and logic flows.
    }

    @Test
    public void testVerifyNonDup_BothExplicit_SameClass_SameType_ThrowsException() {
        AnnotatedWithParams oldOne = mock(AnnotatedWithParams.class);
        AnnotatedWithParams newOne = mock(AnnotatedWithParams.class);
        Class<?> type = String.class;

        when(oldOne.getClass()).thenReturn(oldOne.getClass());
        when(newOne.getClass()).thenReturn(newOne.getClass());
        when(oldOne.getRawParameterType(0)).thenReturn(type);
        when(newOne.getRawParameterType(0)).thenReturn(type);

        creatorCollector.verifyNonDup(oldOne, 0, true);

        try {
            creatorCollector.verifyNonDup(newOne, 0, true);
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertTrue(e.getMessage().contains("Conflicting"));
        }
    }

    @Test
    public void testVerifyNonDup_BothExplicit_SameClass_NewIsGeneric_ShouldReturn() {
        AnnotatedWithParams oldOne = mock(AnnotatedWithParams.class);
        AnnotatedWithParams newOne = mock(AnnotatedWithParams.class);

        // oldOne is String, newOne is Object (more generic)
        // Note: logic says if newType.isAssignableFrom(oldType) -> use old.
        // If oldType = String, newType = Object. Object.isAssignableFrom(String) is true.
        Class<?> oldType = String.class;
        Class<?> newType = Object.class;

        when(oldOne.getClass()).thenReturn(oldOne.getClass());
        when(newOne.getClass()).thenReturn(newOne.getClass());
        when(oldOne.getRawParameterType(0)).thenReturn(oldType);
        when(newOne.getRawParameterType(0)).thenReturn(newType);

        creatorCollector.verifyNonDup(oldOne, 0, true);
        creatorCollector.verifyNonDup(newOne, 0, true);

        // Should not throw exception because newType is more generic
    }

    @Test
    public void testVerifyNonDup_BothExplicit_SameClass_NewIsSpecific_ShouldOverride() {
        AnnotatedWithParams oldOne = mock(AnnotatedWithParams.class);
        AnnotatedWithParams newOne = mock(AnnotatedWithParams.class);

        // oldOne is Object, newOne is String (more specific)
        Class<?> oldType = Object.class;
        Class<?> newType = String.class;

        when(oldOne.getClass()).thenReturn(oldOne.getClass());
        when(newOne.getClass()).thenReturn(newOne.getClass());
        when(oldOne.getRawParameterType(0)).thenReturn(oldType);
        when(newOne.getRawParameterType(0)).thenReturn(newType);

        creatorCollector.verifyNonDup(oldOne, 0, true);
        creatorCollector.verifyNonDup(newOne, 0, true);

        // Should not throw exception, newOne overrides oldOne
    }

    @Test
    public void testVerifyNonDup_Implicit_ExistingExplicit_ShouldNotVerify() {
        AnnotatedWithParams oldOne = mock(AnnotatedWithParams.class);
        AnnotatedWithParams newOne = mock(AnnotatedWithParams.class);

        // Setup: existing explicit
        creatorCollector.verifyNonDup(oldOne, 0, true);

        // New one is implicit (explicit = false)
        // The code says: if ((_explicitCreators & mask) != 0) { if (!explicit) return; }
        creatorCollector.verifyNonDup(newOne, 0, false);

        // Should not throw
    }

    @Test
    public void testVerifyNonDup_Implicit_ExistingImplicit_ShouldVerify() {
        AnnotatedWithParams oldOne = mock(AnnotatedWithParams.class);
        AnnotatedWithParams newOne = mock(AnnotatedWithParams.class);

        Class<?> type = String.class;
        when(oldOne.getClass()).thenReturn(oldOne.getClass());
        when(newOne.getClass()).thenReturn(newOne.getClass());
        when(oldOne.getRawParameterType(0)).thenReturn(type);
        when(newOne.getRawParameterType(0)).thenReturn(type);

        // First one is implicit
        creatorCollector.verifyNonDup(oldOne, 0, false);

        // Second one is implicit -> verify = !explicit -> verify = true.
        // Since types are same, it should throw.
        try {
            creatorCollector.verifyNonDup(newOne, 0, false);
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            // Success
        }
    }

    @Test
    public void testVerifyNonDup_DifferentClasses_ShouldNotThrow() {
        AnnotatedWithParams oldOne = mock(AnnotatedWithParams.class);
        AnnotatedWithParams newOne = mock(AnnotatedWithParams.class);

        // Use different concrete classes for the AnnotatedWithParams implementation
        // to bypass the (oldOne.getClass() == newOne.getClass()) check
        AnnotatedWithParams oldOneReal = spy(new AnnotatedWithParamsImpl());
        AnnotatedWithParams newOneReal = spy(new AnnotatedWithParamsImpl());

        creatorCollector.verifyNonDup(oldOneReal, 0, true);
        creatorCollector.verifyNonDup(newOneReal, 0, true);

        // Should not throw because classes are different
    }

    // Helper class to avoid Mockito issues with class identity checks
    private static class AnnotatedWithParamsImpl implements AnnotatedWithParams {
        @Override public Class<?> getRawParameterType(int i) { return String.class; }
        // Add other necessary overrides for AnnotatedWithParams if required by compiler
    }
}
